package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import com.greenocean.backend.common.exception.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.junit.jupiter.api.*;import java.util.*;import java.time.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa","greenocean.clinic.reputation-enabled=true","greenocean.clinic.public-reputation-enabled=true","greenocean.clinic.reputation-keys=reputation-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.reputation-current-key=reputation-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseP4Test extends PhaseP4Fixtures {
 @Test void genuineDeliveredAppointmentAndExplicitChoicesAreRequired(){assertThatThrownBy(()->reputation.feedback(learner.id(),input(appointment,5,true,true))).isInstanceOf(ConflictException.class);UUID a=delivered();var in=input(a,2,false,false);UUID id=reputation.feedback(learner.id(),in);assertThat(reputation.feedback(learner.id(),in)).isEqualTo(id);assertThatThrownBy(()->reputation.feedback(other.id(),input(a,5,true,true))).isInstanceOf(NotFoundException.class);assertThatThrownBy(()->reputation.review(reviewer.id(),reviewer.session(),id,new ProfessionalReputation.Review(1,"PUBLISH","Synthetic redacted experience",true,"PRIVACY_REDACTED"))).isInstanceOf(ForbiddenException.class);}
 @Test void publicFeedbackContainsNoPatientIdentityAppointmentOrPrivateWording(){UUID id=feedback();reputation.review(reviewer.id(),reviewer.session(),id,new ProfessionalReputation.Review(1,"PUBLISH","I felt listened to during the appointment.",true,"PRIVACY_REDACTED"));String published=reputation.publicFeedback(other.id(),author.id(),"TEXT").toString();assertThat(published).contains("I felt listened to").doesNotContain(learner.id().toString(),appointment.toString(),"patient_id","created_at","Synthetic private experience");}
 @Test void adminAndProfessionalCannotReadPrivateFeedbackThroughTheirRoles(){UUID id=feedback();role(issuer.id(),"CLINIC_REPUTATION_OPERATOR");db.update("DELETE FROM user_roles WHERE user_id=? AND role_id=(SELECT id FROM roles WHERE name='CLINIC_REPUTATION_OPERATOR')",issuer.id());assertThatThrownBy(()->reputation.privateFeedback(issuer.id(),issuer.session(),id)).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->reputation.privateFeedback(author.id(),author.session(),id)).isInstanceOf(ForbiddenException.class);}
 @Test void selfModerationAndIdentifyingPublicTextAreRejected(){UUID id=feedback();role(author.id(),"CLINIC_REPUTATION_OPERATOR");assertThatThrownBy(()->reputation.review(author.id(),author.session(),id,new ProfessionalReputation.Review(1,"APPROVE",null,false,"SOURCE_CHECKED"))).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->reputation.review(reviewer.id(),reviewer.session(),id,new ProfessionalReputation.Review(1,"PUBLISH","Email patient@example.test for clinical details",true,"PRIVACY_REDACTED"))).isInstanceOf(IllegalArgumentException.class);}
 @Test void patientWithdrawalPreservesHistoryAndStopsPublication(){UUID id=feedback();reputation.review(reviewer.id(),reviewer.session(),id,new ProfessionalReputation.Review(1,"PUBLISH","A respectful appointment experience.",true,"PRIVACY_REDACTED"));reputation.withdraw(learner.id(),id);assertThat(reputation.publicFeedback(other.id(),author.id(),"TEXT")).isEmpty();assertThat(db.queryForObject("SELECT count(*) FROM clinic_feedback_versions WHERE feedback_id=?",Integer.class,id)).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM clinic_feedback_events WHERE feedback_id=?",Integer.class,id)).isEqualTo(3);}
 @Test void newProfessionalsReceiveNoInventedScoreOrSmallPatientCount(){assertThat(ownRank()).containsEntry("experienceIndicator",null).containsEntry("verifiedPatientCount",null).containsEntry("sampleBand","INSUFFICIENT_EVIDENCE");}
 @Test void repeatedFreeSessionsFromOnePatientDoNotBecomeFiveIndependentVotes(){for(int day=1;day<=5;day++){UUID id=reputation.feedback(learner.id(),input(historical(learner,day),5,true,false));approve(id);}assertThat(ownRank()).containsEntry("experienceIndicator",null);}
 @Test void distinctVerifiedParticipationUsesBoundedConservativeVersionedIndex(){distinctPatients(5);var r=ownRank();assertThat((Double)r.get("experienceIndicator")).isBetween(0.0,95.0);assertThat(r.get("verifiedPatientCount")).isEqualTo(5);assertThat(r.get("methodVersion")).isNotNull();assertThat(r).doesNotContainKeys("patient_id","revenue","subscription","diagnosis");}
 @Test void subscriptionsAndRevenueDoNotBuyRankingOrProfessionalEligibility(){var before=ownRank();UUID plan=commerce.plan(issuer.id(),"qa-admin-"+UUID.randomUUID(),List.of("ADMIN_REPORTS"),0,7);commerce.subscribe(author.id(),plan,UUID.randomUUID(),true);assertThat(ownRank()).isEqualTo(before);db.update("UPDATE professional_verifications SET qualification_state='REVOKED' WHERE professional_user_id=?",author.id());assertThat(reputation.rankings(learner.id(),"PSYCHOLOGIST","TEXT").toString()).doesNotContain(author.id().toString());}
 @Test void unreviewedAllegationDoesNotBecomeARankingPenalty(){var before=ownRank();reputation.openCase(learner.id(),author.id(),null,appointment,"CONDUCT","Synthetic unproven allegation requiring independent review");assertThat(ownRank()).isEqualTo(before);}
 @Test void independentMethodologyApprovalAndImmutabilityAreRequired(){UUID draft=reputation.method(issuer.id(),issuer.session(),new ProfessionalReputation.Method("self-"+UUID.randomUUID(),180,5,10,70,2,4,30,Instant.now().plusSeconds(300)));assertThatThrownBy(()->reputation.approveMethod(issuer.id(),issuer.session(),draft)).isInstanceOf(ForbiddenException.class);}
 @Test void weeklyNewcomerSelectionIsIndependentBoundedAndTruthfullyLabelled(){scheduling.slot(author.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(7200),Instant.now().plusSeconds(9000),"TEXT",0,"Asia/Tehran",true));LocalDate monday=LocalDate.now(ZoneOffset.UTC).with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));UUID batch=reputation.proposeWeekly(issuer.id(),issuer.session(),"PSYCHOLOGIST","TEXT",monday,"NEW_DISCOVERY");assertThatThrownBy(()->reputation.publishWeekly(issuer.id(),issuer.session(),batch)).isInstanceOf(ForbiddenException.class);reputation.publishWeekly(reviewer.id(),reviewer.session(),batch);String output=reputation.weekly(learner.id(),"PSYCHOLOGIST","TEXT").toString();assertThat(output).contains("earned recognition","not a medical endorsement").doesNotContain("patient_id","sponsored=true");db.update("UPDATE professional_verifications SET qualification_state='SUSPENDED' WHERE professional_user_id=?",author.id());assertThat(reputation.weekly(learner.id(),"PSYCHOLOGIST","TEXT")).isEmpty();}
 @Test void feedbackCorrectionRequiresCurrentRevisionAndNewModeration(){UUID id=feedback();approve(id);var next=new ProfessionalReputation.Feedback(appointment,1,1,"Synthetic corrected private experience",true,false,UUID.randomUUID());assertThat(reputation.feedback(learner.id(),next)).isEqualTo(id);assertThat(reputation.privateFeedback(learner.id(),learner.session(),id)).containsEntry("state","SUBMITTED");assertThatThrownBy(()->reputation.review(reviewer.id(),reviewer.session(),id,new ProfessionalReputation.Review(1,"APPROVE",null,false,"SOURCE_CHECKED"))).isInstanceOf(ConflictException.class);}
 @Test void unknownHistoricalProfessionDoesNotAcquireTheCurrentProfessionScore(){for(int i=0;i<5;i++){var patient=PhaseIFixtures.member(db,users,tokens);UUID id=reputation.feedback(patient.id(),input(historical(patient,i+1,false),5,true,false));approve(id);}assertThat(ownRank()).containsEntry("experienceIndicator",null);}
 @Test void negativeFeedbackCannotRemoveCurrentCareOrNewFreeBooking(){UUID a=delivered();UUID feedback=reputation.feedback(learner.id(),input(a,1,true,false));approve(feedback);UUID slot=scheduling.slot(author.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(7200),Instant.now().plusSeconds(9000),"TEXT",0,"Asia/Tehran",true));commerce.offer(author.id(),slot,policy,false);assertThat(commerce.book(learner.id(),new ClinicCommerce.Booking(slot,UUID.randomUUID(),2,policy,0,true))).containsEntry("status","CONFIRMED");}
 @Test void changedAvailabilityInvalidatesAWeeklyProposalInsteadOfPublishingStaleEvidence(){UUID slot=scheduling.slot(author.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(7200),Instant.now().plusSeconds(9000),"TEXT",0,"Asia/Tehran",true));LocalDate week=LocalDate.now(ZoneOffset.UTC).with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));UUID batch=reputation.proposeWeekly(issuer.id(),issuer.session(),"PSYCHOLOGIST","TEXT",week,"NEW_DISCOVERY");scheduling.cancelSlot(author.id(),slot,1);assertThatThrownBy(()->reputation.publishWeekly(reviewer.id(),reviewer.session(),batch)).isInstanceOf(ConflictException.class);}
}
